{"content":"/**
 * Server-name validation, YAML emission, and cordis.patch.yml block surgery.
 *
 * The plugin owns exactly one marked block inside the profile patch layer:
 *
 *   # --- dsh-mcp managed (auto-generated; do not edit) ---
 *   - insert:
 *       - id: mcp-<serverName>
 *         name: '@deepseek-ai/dsh-mcp-client'
 *         config: …
 *   # --- end dsh-mcp managed ---
 *
 * Everything outside the markers is preserved byte-for-byte. The source of
 * truth is the JSON state file (~/.dsh/dsh-mcp.json); the YAML block is
 * regenerated from it on every mutation, so no YAML *parser* is needed —
 * only this emitter. The web surface hot-reloads cordis.patch.yml, so a
 * rewrite is the whole "apply" path.
 *
 * Pure module: no cordis imports, fully unit-testable.
 *
 * @module dsh-mcp/patch
 */

import { mkdirSync, readFileSync, renameSync, writeFileSync, existsSync } from 'node:fs'
import { dirname } from 'node:path'

/** Official MCP client bridge module name (must match the harness package). */
export const MCP_CLIENT_MODULE = '@deepseek-ai/dsh-mcp-client'

/** Loader entry id prefix this plugin manages. */
export const ENTRY_ID_PREFIX = 'mcp-'

/** Managed-block markers inside cordis.patch.yml. */
export const BLOCK_BEGIN = '# --- dsh-mcp managed (auto-generated; do not edit) ---'
export const BLOCK_END = '# --- end dsh-mcp managed ---'

/** serverName rule enforced by @deepseek-ai/dsh-mcp-client. */
export const SERVER_NAME_RE = /^[A-Za-z0-9_-]{1,32}$/

/**
 * @typedef {Object} ServerSpec
 * @property {'streamable-http'|'stdio'} transport
 * @property {string} [url]      - streamable-http endpoint
 * @property {Record<string,string>} [headers]
 * @property {string} [command]  - stdio executable
 * @property {string[]} [args]
 * @property {Record<string,string>} [env]
 * @property {string} [cwd]
 * @property {boolean} [disabled]
 */

/**
 * Loader entry id for one server.
 * @param {string} serverName
 */
export function entryIdOf(serverName) {
  return `${ENTRY_ID_PREFIX}${serverName}`
}

/**
 * Quote one scalar as a YAML single-quoted string. Always quoting keeps the
 * emitter trivially correct for urls, tokens, and paths with spaces.
 * @param {string} value
 */
export function yamlString(value) {
  return `'${String(value).replaceAll("'", "''")}'`
}

/**
 * Emit one server's config map (indented under `config:`).
 * @param {ServerSpec} spec
 * @param {string} serverName
 * @returns {string[]} yaml lines at the config-child indent (8 spaces)
 */
function configLines(spec, serverName) {
  const lines = []
  lines.push(`        serverName: ${yamlString(serverName)}`)
  lines.push(`        transport: ${spec.transport}`)
  if (spec.transport === 'streamable-http') {
    lines.push(`        url: ${yamlString(spec.url ?? '')}`)
    for (const [k, v] of Object.entries(spec.headers ?? {})) {
      if (lines.indexOf('        headers:') === -1) lines.push('        headers:')
      lines.push(`          ${k}: ${yamlString(v)}`)
    }
  } else {
    lines.push(`        command: ${yamlString(spec.command ?? '')}`)
    if (spec.args?.length) {
      lines.push(`        args:`)
      for (const a of spec.args) lines.push(`          - ${yamlString(a)}`)
    }
    if (spec.cwd) lines.push(`        cwd: ${yamlString(spec.cwd)}`)
    const env = Object.entries(spec.env ?? {})
    if (env.length) {
      lines.push(`        env:`)
      for (const [k, v] of env) lines.push(`          ${k}: ${yamlString(v)}`)
    }
  }
  return lines
}

/**
 * Emit the full managed block for the state, or '' when no servers exist
 * (the block is then removed from the patch file entirely).
 * @param {Record<string, ServerSpec>} servers
 * @returns {string}
 */
export function emitBlock(servers) {
  const names = Object.keys(servers).sort()
  if (names.length === 0) return ''
  const lines = [BLOCK_BEGIN]
  for (const name of names) {
    const spec = servers[name]
    lines.push('- insert:')
    lines.push(`    - id: ${entryIdOf(name)}`)
    lines.push(`      name: ${yamlString(MCP_CLIENT_MODULE)}`)
    lines.push('      config:')
    lines.push(...configLines(spec, name))
    if (spec.disabled) lines.push('      disabled: true')
  }
  lines.push(BLOCK_END)
  return lines.join('\n')
}

/**
 * Splice a new managed block into existing patch-file text. Text outside the
 * markers survives verbatim; a stray begin/end marker pair is always
 * normalized to exactly one block at the end of the file.
 * @param {string} oldText - current cordis.patch.yml content ('' when absent)
 * @param {string} block - result of {@link emitBlock} ('' removes the block)
 * @returns {string} new file content
 */
export function spliceBlock(oldText, block) {
  // Strip any previous managed block (tolerant of missing end marker).
  const begin = oldText.indexOf(BLOCK_BEGIN)
  let body = oldText
  if (begin !== -1) {
    const end = oldText.indexOf(BLOCK_END, begin)
    const stop = end === -1 ? oldText.length : end + BLOCK_END.length
    body = oldText.slice(0, begin) + oldText.slice(stop)
  }
  body = body.replace(/\s+$/u, '')
  if (block === '') return body === '' ? '[]\n' : `${body}\n`
  if (body === '' || body === '[]') return `${block}\n`
  return `${body}\n\n${block}\n`
}

/** Empty state file shape. */
export function emptyState() {
  return { version: 1, servers: {} }
}

/**
 * Read the JSON state file; a missing or malformed file yields empty state
 * (the managed block is regenerated on the next mutation anyway).
 * @param {string} stateFile
 */
export function readState(stateFile) {
  try {
    const raw = JSON.parse(readFileSync(stateFile, 'utf8'))
    if (typeof raw !== 'object' || raw === null) return emptyState()
    const servers = typeof raw.servers === 'object' && raw.servers !== null ? raw.servers : {}
    return { version: 1, servers }
  } catch {
    return emptyState()
  }
}

/**
 * Persist state and regenerate the patch-file block atomically.
 * @param {string} stateFile
 * @param {string} patchFile
 * @param {ReturnType<typeof emptyState>} state
 */
export function writeStateAndPatch(stateFile, patchFile, state) {
  mkdirSync(dirname(stateFile), { recursive: true })
  const tmp = `${stateFile}.tmp-${process.pid}`
  writeFileSync(tmp, `${JSON.stringify(state, null, 2)}\n`, { mode: 0o600 })
  renameSync(tmp, stateFile)

  const oldText = existsSync(patchFile) ? readFileSync(patchFile, 'utf8') : ''
  const next = spliceBlock(oldText, emitBlock(state.servers))
  mkdirSync(dirname(patchFile), { recursive: true })
  const ptmp = `${patchFile}.tmp-${process.pid}`
  writeFileSync(ptmp, next)
  renameSync(ptmp, patchFile)
}

/**
 * Display-safe endpoint: strips userinfo/query/hash and truncates a long
 * final path segment (usually a webhook token). Never throws.
 * @param {string} url
 */
export function sanitizeUrl(url) {
  try {
    const u = new URL(url)
    const segs = u.pathname.split('/').map((s) => (s.length > 24 ? `${s.slice(0, 12)}…` : s))
    return `${u.origin}${segs.join('/')}`
  } catch {
    return String(url).slice(0, 64)
  }
}
