{"content":"/**
 * Slash-command surface: `/mcp` (runtime status, read-only) and
 * `/mcp-config` (mutates the JSON state + regenerates the managed block in
 * cordis.patch.yml; the web surface hot-reloads it).
 *
 * Handlers are thin shells over pure functions so every behavior is
 * testable without a cordis context.
 *
 * @module dsh-mcp/commands
 */

import { MCP_CLIENT_MODULE, SERVER_NAME_RE, entryIdOf, sanitizeUrl } from './patch.js'

/** Cordis FiberState enum projected to labels (numeric cross-package enum). */
const FIBER_LABEL = { 0: 'pending', 1: 'loading', 2: 'active', 3: 'failed', 5: 'unloading' }

const USAGE_MCP = '用法：/mcp | /mcp <服务器> | /mcp <服务器> tools'
const USAGE_CONFIG = [
  '用法：',
  '  /mcp-config list',
  '  /mcp-config add <名称> http <url> [-H "Header: 值"]…',
  '  /mcp-config add <名称> stdio <命令> [参数…] [-E KEY=值]…',
  '  /mcp-config remove <名称>',
  '  /mcp-config enable <名称> | /mcp-config disable <名称>',
  '名称规则：[A-Za-z0-9_-]{1,32}；改动写入 cordis.patch.yml 后由 web 端热重载生效。',
].join('\n')

/**
 * Split rawInput shell-ish: double/single quotes group, backslash escapes
 * inside double quotes. Good enough for URLs and header values with spaces.
 * @param {string} input
 * @returns {string[]}
 */
export function tokenize(input) {
  const out = []
  const re = /"((?:\\.|[^"\\])*)"|'([^']*)'|(\S+)/gu
  let m
  while ((m = re.exec(input)) !== null) {
    if (m[1] !== undefined) out.push(m[1].replace(/\\(.)/gu, '$1'))
    else if (m[2] !== undefined) out.push(m[2])
    else out.push(m[3])
  }
  return out
}

/**
 * Parse `/mcp-config add …` tokens into a ServerSpec.
 * @param {string[]} tokens - tokens after `add <name>`
 * @returns {{ok: true, spec: object} | {ok: false, error: string}}
 */
export function parseAdd(tokens) {
  if (tokens.length === 0) return { ok: false, error: USAGE_CONFIG }
  if (tokens[0] === 'http') {
    const url = tokens[1]
    if (url === undefined || !/^https?:\/\//u.test(url)) {
      return { ok: false, error: `需要 http(s) URL。\n${USAGE_CONFIG}` }
    }
    const headers = {}
    for (let i = 2; i < tokens.length; i += 1) {
      if (tokens[i] !== '-H' || tokens[i + 1] === undefined) {
        return { ok: false, error: `无法解析参数 "${tokens[i]}"。\n${USAGE_CONFIG}` }
      }
      const kv = tokens[i + 1]
      const colon = kv.indexOf(':')
      if (colon < 1) return { ok: false, error: `Header 格式应为 "名称: 值"，收到 "${kv}"。` }
      headers[kv.slice(0, colon).trim()] = kv.slice(colon + 1).trim()
      i += 1
    }
    return { ok: true, spec: { transport: 'streamable-http', url, ...(Object.keys(headers).length ? { headers } : {}) } }
  }
  if (tokens[0] === 'stdio') {
    const command = tokens[1]
    if (command === undefined) return { ok: false, error: `缺少命令。\n${USAGE_CONFIG}` }
    const args = []
    const env = {}
    for (let i = 2; i < tokens.length; i += 1) {
      if (tokens[i] === '-E') {
        const kv = tokens[i + 1]
        if (kv === undefined || !/^[^=]+=/u.test(kv)) {
          return { ok: false, error: `-E 需要 KEY=值，收到 "${kv ?? ''}"。` }
        }
        const eq = kv.indexOf('=')
        env[kv.slice(0, eq)] = kv.slice(eq + 1)
        i += 1
      } else {
        args.push(tokens[i])
      }
    }
    return { ok: true, spec: { transport: 'stdio', command, ...(args.length ? { args } : {}), ...(Object.keys(env).length ? { env } : {}) } }
  }
  return { ok: false, error: `未知传输 "${tokens[0]}"（应为 http 或 stdio）。\n${USAGE_CONFIG}` }
}

/**
 * One-line target description of a spec/loader config.
 * @param {object} spec
 */
export function describeTarget(spec) {
  if (spec.transport === 'streamable-http') return sanitizeUrl(spec.url ?? '')
  const args = Array.isArray(spec.args) ? spec.args.join(' ') : ''
  return `${spec.command ?? ''}${args === '' ? '' : ` ${args}`}`
}

/**
 * Read loader rows of the official MCP client into plain views.
 * Defensive: config may be absent or contain !!js expression nodes.
 * @param {Iterable<object>} entries - ctx.loader.entries()
 */
export function loaderServerViews(entries) {
  const views = []
  for (const entry of entries) {
    if (entry?.options?.name !== MCP_CLIENT_MODULE) continue
    const config = entry.options.config ?? {}
    const serverName = typeof config.serverName === 'string' ? config.serverName : `entry:${entry.options.id}`
    views.push({
      entryId: entry.options.id,
      serverName,
      disabled: Boolean(entry.disabled),
      fiber: entry.fiber === undefined ? null : (FIBER_LABEL[entry.fiber.state] ?? `state:${entry.fiber.state}`),
      transport: typeof config.transport === 'string' ? config.transport : '?',
      target: describeTarget(config),
      managed: String(entry.options.id ?? '').startsWith('mcp-'),
    })
  }
  views.sort((a, b) => a.serverName.localeCompare(b.serverName))
  return views
}

/**
 * Group registered tool schemas by mcp__<server>__ namespace.
 * @param {Array<{name?: string, description?: string}>} schemas
 * @returns {Map<string, Array<{name: string, description: string}>>}
 */
export function groupTools(schemas) {
  const groups = new Map()
  for (const schema of schemas ?? []) {
    const name = schema?.name
    if (typeof name !== 'string' || !name.startsWith('mcp__')) continue
    const rest = name.slice(5)
    const sep = rest.indexOf('__')
    if (sep < 1) continue
    const server = rest.slice(0, sep)
    if (!groups.has(server)) groups.set(server, [])
    groups.get(server).push({ name, description: typeof schema.description === 'string' ? schema.description : '' })
  }
  for (const list of groups.values()) list.sort((a, b) => a.name.localeCompare(b.name))
  return groups
}

/**
 * Render the `/mcp` overview.
 * @param {ReturnType<typeof loaderServerViews>} views
 * @param {Map<string, Array>} groups
 */
export function renderOverview(views, groups) {
  if (views.length === 0) {
    return '未配置 MCP 服务器（组合中没有 @deepseek-ai/dsh-mcp-client 条目）。\n用 /mcp-config add 添加一个。'
  }
  const lines = [`MCP 服务器（${views.length} 个）：`]
  for (const v of views) {
    const tools = groups.get(v.serverName) ?? []
    const state = v.disabled ? '已停用' : '已启用'
    const fiber = v.fiber === null ? '—' : v.fiber
    const managed = v.managed ? '' : '（非 dsh-mcp 管理）'
    lines.push(`- ${v.serverName} [${v.entryId}] ${v.transport} ${v.target} ${managed}`)
    lines.push(`  | ${tools.length} 个工具 | ${state} | fiber: ${fiber}`)
  }
  return lines.join('\n')
}

/**
 * Render one server's detail / tool list.
 * @param {object} view
 * @param {Array<{name: string, description: string}>} tools
 * @param {boolean} withTools
 */
export function renderServer(view, tools, withTools) {
  const lines = [
    `${view.serverName} [${view.entryId}]`,
    `  transport: ${view.transport}`,
    `  target: ${view.target}`,
    `  ${view.disabled ? '已停用' : '已启用'} | fiber: ${view.fiber ?? '—'} | 工具 ${tools.length} 个`,
  ]
  if (withTools) {
    if (tools.length === 0) {
      lines.push('  （无已注册工具：服务器未连接、同步失败或已停用）')
    } else {
      lines.push('  工具（模型可见名）：')
      for (const t of tools) {
        const desc = t.description === '' ? '' : ` — ${t.description.split('\n')[0].slice(0, 80)}`
        lines.push(`    ${t.name}${desc}`)
      }
    }
  }
  return lines.join('\n')
}

/**
 * Build the `/mcp` command definition.
 * @param {(name?: string) => {views: object[], groups: Map<string, Array>}} snapshot
 */
export function mcpStatusCommand(snapshot) {
  return {
    name: 'mcp',
    description: '查看所有 MCP 服务器状态（transport、目标、工具数、启用状态、fiber）',
    input: { hint: '[服务器] [tools]' },
    handler: ({ rawInput }) => {
      const tokens = tokenize(rawInput.trim())
      const { views, groups } = snapshot()
      if (tokens.length === 0) return { kind: 'success', text: renderOverview(views, groups) }
      const name = tokens[0]
      const view = views.find((v) => v.serverName === name || v.entryId === name)
      if (view === undefined) {
        const known = views.map((v) => v.serverName).join(', ')
        return { kind: 'error', text: `未知 MCP 服务器 "${name}"（已配置：${known === '' ? '无' : known}）` }
      }
      const tools = groups.get(view.serverName) ?? []
      if (tokens.length === 1) return { kind: 'success', text: renderServer(view, tools, false) }
      if (tokens[1] === 'tools') return { kind: 'success', text: renderServer(view, tools, true) }
      return { kind: 'error', text: USAGE_MCP }
    },
  }
}

/**
 * Build the `/mcp-config` command definition.
 * @param {object} store - { list(), add(name, spec), remove(name), setDisabled(name, disabled) }
 *   each mutating method returns {changed: boolean, message?: string}
 */
export function mcpConfigCommand(store) {
  return {
    name: 'mcp-config',
    description: '配置 MCP 服务器：add/remove/enable/disable/list（写入 cordis.patch.yml，web 端热重载生效）',
    input: { hint: 'list | add <名称> http <url> [-H "K: V"]… | add <名称> stdio <命令> [参数…] | remove <名称> | enable|disable <名称>' },
    handler: ({ rawInput }) => {
      const tokens = tokenize(rawInput.trim())
      const sub = tokens[0]
      if (sub === undefined || sub === 'help') return { kind: 'success', text: USAGE_CONFIG }

      if (sub === 'list') {
        const servers = store.list()
        const names = Object.keys(servers).sort()
        if (names.length === 0) return { kind: 'success', text: `（dsh-mcp 尚未管理任何服务器）\n${USAGE_CONFIG}` }
        const lines = [`dsh-mcp 管理的服务器（${names.length} 个）：`]
        for (const n of names) {
          const s = servers[n]
          lines.push(`- ${n} [${entryIdOf(n)}] ${s.transport} ${describeTarget(s)}${s.disabled ? '（已停用）' : ''}`)
        }
        return { kind: 'success', text: lines.join('\n') }
      }

      if (sub === 'add') {
        const name = tokens[1]
        if (name === undefined || !SERVER_NAME_RE.test(name)) {
          return { kind: 'error', text: `名称需匹配 [A-Za-z0-9_-]{1,32}。\n${USAGE_CONFIG}` }
        }
        const parsed = parseAdd(tokens.slice(2))
        if (!parsed.ok) return { kind: 'error', text: parsed.error }
        const result = store.add(name, parsed.spec)
        if (!result.changed) return { kind: 'error', text: result.message }
        return {
          kind: 'success',
          text: `已添加 "${name}"（${parsed.spec.transport} ${describeTarget(parsed.spec)}）。\n已写入 cordis.patch.yml，web 端热重载后生效；用 /mcp 查看连接结果。`,
        }
      }

      if (sub === 'remove') {
        const name = tokens[1]
        if (name === undefined) return { kind: 'error', text: USAGE_CONFIG }
        const result = store.remove(name)
        if (!result.changed) return { kind: 'error', text: result.message }
        return { kind: 'success', text: `已移除 "${name}" 并重写 cordis.patch.yml；热重载后其工具将注销。` }
      }

      if (sub === 'enable' || sub === 'disable') {
        const name = tokens[1]
        if (name === undefined) return { kind: 'error', text: USAGE_CONFIG }
        const result = store.setDisabled(name, sub === 'disable')
        if (!result.changed) return { kind: 'error', text: result.message }
        return { kind: 'success', text: `已${sub === 'disable' ? '停用' : '启用'} "${name}"；热重载后生效。` }
      }

      return { kind: 'error', text: `未知子命令 "${sub}"。\n${USAGE_CONFIG}` }
    },
  }
}
