 * dsh-mcp — MCP manager for DeepSeek Harness.
 *
 * Host-only cordis plugin (no client bundle). Two human commands over the
 * official MCP client bridge (@deepseek-ai/dsh-mcp-client):
 *
 * - `/mcp`        — read-only runtime status: one row per loader entry with
 *                   transport, sanitized target, live tool count (from
 *                   ctx.tools), enabled state, and fiber phase.
 * - `/mcp-config` — configuration writer: add/remove/enable/disable servers.
 *                   Servers are kept in a JSON state file (~/.dsh/dsh-mcp.json)
 *                   and rendered into a marked, auto-generated block inside
 *                   the profile cordis.patch.yml. The web surface hot-reloads
 *                   patch edits, so a mutation takes effect within seconds —
 *                   the mcp-client bridge then connects and registers its
 *                   tools as `mcp__<serverName>__<tool>`.
 *
 * Function plugin — no default export (the Loader unwraps
 * `exports.default ?? exports`).
 *
 * @module dsh-mcp
 */

import { homedir } from 'node:os'
import { join } from 'node:path'
import { entryIdOf, readState, writeStateAndPatch } from './patch.js'
import { groupTools, loaderServerViews, mcpConfigCommand, mcpStatusCommand } from './commands.js'

/** Stable cordis plugin name. */
export const name = 'dsh-mcp'

/** Hard services: command registry, tool registry (tool counts), loader (live rows). */
export const inject = ['commands', 'tools', 'loader']

export { entryIdOf, readState, writeStateAndPatch } from './patch.js'
export * from './commands.js'

/**
 * Resolve plugin config into concrete paths.
 * @param {object} [config]
 */
export function resolveConfig(config = {}) {
  const dshHome = process.env.DSH_HOME ?? join(homedir(), '.dsh')
  const profile = typeof config.profile === 'string' && config.profile !== '' ? config.profile : 'web'
  return {
    stateFile: typeof config.stateFile === 'string' ? config.stateFile : join(dshHome, 'dsh-mcp.json'),
    patchFile: typeof config.patchFile === 'string' ? config.patchFile : join(dshHome, 'profiles', profile, 'cordis.patch.yml'),
  }
}

/**
 * State-file backed store exposed to the /mcp-config command. Every mutation
 * rewrites the JSON state and the managed patch block atomically.
 * @param {{stateFile: string, patchFile: string}} paths
 */
export function makeStore(paths) {
  const mutate = (fn) => {
    const state = readState(paths.stateFile)
    const result = fn(state.servers)
    if (result.changed) writeStateAndPatch(paths.stateFile, paths.patchFile, state)
    return result
  }
  return {
    list: () => readState(paths.stateFile).servers,
    add: (serverName, spec) =>
      mutate((servers) => {
        if (servers[serverName] !== undefined) {
          return { changed: false, message: `"${serverName}" 已存在；先 /mcp-config remove ${serverName} 再重新添加。` }
        }
        servers[serverName] = spec
        return { changed: true }
      }),
    remove: (serverName) =>
      mutate((servers) => {
        if (servers[serverName] === undefined) {
          return { changed: false, message: `"${serverName}" 不在 dsh-mcp 管理列表中。` }
        }
        delete servers[serverName]
        return { changed: true }
      }),
    setDisabled: (serverName, disabled) =>
      mutate((servers) => {
        if (servers[serverName] === undefined) {
          return { changed: false, message: `"${serverName}" 不在 dsh-mcp 管理列表中。` }
        }
        servers[serverName] = { ...servers[serverName], disabled }
        return { changed: true }
      }),
  }
}

/**
 * Mount both commands.
 * @param {import('@deepseek-ai/cordis').Context} ctx
 * @param {object} [config]
 */
export function apply(ctx, config) {
  const paths = resolveConfig(config)
  const store = makeStore(paths)

  const snapshot = () => ({
    views: loaderServerViews(ctx.loader.entries()),
    groups: groupTools(ctx.tools.schemas()),
  })

  ctx.effect(() => ctx.commands.register(mcpStatusCommand(snapshot)), 'dsh-mcp: /mcp command')
  ctx.effect(() => ctx.commands.register(mcpConfigCommand(store)), 'dsh-mcp: /mcp-config command')
}
