  const profile = typeof config.profile === 'string' && config.profile !== '' ? config.profile : 'web'
  return {
    stateFile: typeof config.stateFile === 'string' ? config.stateFile : join(dshHome, 'dsh-mcp.json'),
    patchFile: typeof config.patchFile === 'string' ? config.patchFile : join(dshHome, 'profiles', profile, 'cordis.patch.yml'),
  }
}

/**
 * State-file backed store exposed to the /mcp-config command. Every mutation
 * rewrites the JSON state and the managed patch block atomically.
 * @param {{stateFile: string, patchFile: string}} paths
 */
export function makeStore(paths) {
  const mutate = (fn) => {
    const state = readState(paths.stateFile)
    const result = fn(state.servers)
    if (result.changed) writeStateAndPatch(paths.stateFile, paths.patchFile, state)
    return result
  }
  return {
    list: () => readState(paths.stateFile).servers,
    add: (serverName, spec) =>
      mutate((servers) => {
        if (servers[serverName] !== undefined) {
          return { changed: false, message: `"${serverName}" 已存在；先 /mcp-config remove ${serverName} 再重新添加。` }
        }
        servers[serverName] = spec
        return { changed: true }
      }),
    remove: (serverName) =>
      mutate((servers) => {
        if (servers[serverName] === undefined) {
          return { changed: false, message: `"${serverName}" 不在 dsh-mcp 管理列表中。` }
        }
        delete servers[serverName]
        return { changed: true }
      }),
    setDisabled: (serverName, disabled) =>
      mutate((servers) => {
        if (servers[serverName] === undefined) {
          return { changed: false, message: `"${serverName}" 不在 dsh-mcp 管理列表中。` }
        }
        servers[serverName] = { ...servers[serverName], disabled }
        return { changed: true }
      }),
  }
}

/**
 * Mount both commands.
 * @param {import('@deepseek-ai/cordis').Context} ctx
 * @param {object} [config]
 */
export function apply(ctx, config) {
  const paths = resolveConfig(config)
  const store = makeStore(paths)

  const snapshot = () => ({
    views: loaderServerViews(ctx.loader.entries()),
    groups: groupTools(ctx.tools.schemas()),
  })

  ctx.effect(() => ctx.commands.register(mcpStatusCommand(snapshot)), 'dsh-mcp: /mcp command')
  ctx.effect(() => ctx.commands.register(mcpConfigCommand(store)), 'dsh-mcp: /mcp-config command')
}

